package android.view;import android.content.Context;import java.util.*;
public class ViewGroup extends View {public final List<View> children=new ArrayList<>();public ViewGroup(Context c){super(c);}public void addView(View v){if(v.parent!=null)throw new IllegalStateException("View already has a parent");children.add(v);v.parent=this;emit("add",v);}public void removeView(View v){if(children.remove(v)){v.parent=null;emit("remove",v);}}public int getChildCount(){return children.size();}public View getChildAt(int i){return children.get(i);}protected void onLayout(boolean changed,int l,int t,int r,int b){}
public <T extends View> T findViewById(int id){T v=super.findViewById(id);if(v!=null)return v;for(View c:children){v=c.findViewById(id);if(v!=null)return v;}return null;}
public static class LayoutParams{public static final int MATCH_PARENT=-1,WRAP_CONTENT=-2;public int width,height;public LayoutParams(int w,int h){width=w;height=h;}}
public static class MarginLayoutParams extends LayoutParams {public int leftMargin,topMargin,rightMargin,bottomMargin,marginStart;public MarginLayoutParams(int w,int h){super(w,h);}public void setMargins(int l,int t,int r,int b){leftMargin=l;topMargin=t;rightMargin=r;bottomMargin=b;}public void setMarginStart(int s){marginStart=s;}}}
